def P(t,s='Bodyx'): return Paragraph(t,styles[s])
def bullets(xs): return [P('&bull; '+x) for x in xs]
def tbl(data,widths,header=True,small=False):
    rows=[]
    for i,row in enumerate(data): rows.append([P(str(c),'TableHeadx' if header and i==0 else ('Smallx' if small else 'Tablex')) for c in row])
    t=Table(rows,colWidths=widths,repeatRows=1 if header else 0,hAlign='LEFT')
    st=[('GRID',(0,0),(-1,-1),0.35,MID),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]
    if header:
        st += [('BACKGROUND',(0,0),(-1,0),NAVY),('TEXTCOLOR',(0,0),(-1,0),colors.white)]
        for r in range(1,len(data)):
            if r%2==0: st.append(('BACKGROUND',(0,r),(-1,r),LIGHT))
    t.setStyle(TableStyle(st)); return t
def header_footer(c,doc):
    c.saveState(); w,h=A4
    if doc.page>1:
        c.setFillColor(NAVY); c.rect(0,h-13*mm,w,13*mm,fill=1,stroke=0)
        c.setFillColor(colors.white); c.setFont('Helvetica-Bold',8); c.drawString(18*mm,h-8.5*mm,'BIDSURE | SIH26100')
        c.setFont('Helvetica',8); c.drawRightString(w-18*mm,h-8.5*mm,'Security-first architecture plan')
    c.setStrokeColor(MID); c.setLineWidth(.5); c.line(18*mm,13*mm,w-18*mm,13*mm)
    c.setFillColor(MUTED); c.setFont('Helvetica',7.5); c.drawString(18*mm,8*mm,'Prepared 13 September 2026 | Architecture, security and integration plan')
    c.drawRightString(w-18*mm,8*mm,str(doc.page)); c.restoreState()

