# 1 main problem
S += [P('1 Main problem decoded','H1x'),P('SIH26100 asks for automated verification of bidder eligibility across tender documents and multiple government or regulated sources. That creates a compound problem involving identity, privacy, integration authority, data quality, policy interpretation and human accountability.', 'Bodyx')]
S.append(tbl([['PROBLEM LAYER','WHAT CAN GO WRONG','REQUIRED PROPERTY'],['Authority','BidSure calls a source without approval, valid purpose, consent or correct credential','Every source call has an authority record and policy decision'],['Confidentiality','PAN, GST, financial, employment or identity-linked data leaks through logs, prompts, URLs or broad access','Sensitive fields are minimised, masked, encrypted and access controlled'],['Integrity','A response is altered, stale, replayed or mismatched to a different bidder','Responses are timestamped, hashed, source-labelled and bound to a case'],['Availability','A source rate-limits, times out or changes its contract','The platform fails closed, marks Pending and supports controlled retry'],['Interpretation','AI misreads a clause or certificate and creates a false pass/fail','AI proposes structured evidence; deterministic rules and officers control the outcome'],['Accountability','A final decision cannot be reconstructed or challenged','Evidence, rules, source responses and officer actions are immutable and queryable']], [32*mm,72*mm,61*mm],small=True))
S += [Spacer(1,8*mm),P('The architectural thesis','H2x'),P('BidSure is a policy-enforced verification broker. It does not expose government credentials to the browser, does not let an LLM call external systems, does not treat a PDF screenshot as equivalent to a trusted source response, and does not convert uncertainty into a green score.', 'Quote'),PageBreak()]

# 2 trust model
S += [P('2 Trust model and threat boundary','H1x'),P('Design the system as multiple trust zones. The browser is untrusted. The public internet is untrusted. External platforms are trusted only for the specific response they provide and only through approved credentials and routes.', 'Bodyx')]
S.append(tbl([['ZONE','EXAMPLES','TRUST LEVEL','CONTROLLED BY'],['User zone','Bidder browser, officer browser, uploaded files','Untrusted','TLS, authentication, input validation, content scanning'],['Edge zone','DNS, CDN, WAF, rate limiting, reverse proxy','Partially trusted','Allowlist, DDoS controls, request limits, security headers'],['Application zone','Express API, authorization, policy engine, adapter orchestrator','Trusted runtime, least privilege','Private subnets, service identities, code review, network policies'],['Worker zone','OCR, file conversion, adapter jobs, scheduled re-verification','Restricted trusted','Queue isolation, sandboxing, egress allowlists, job-scoped tokens'],['Data zone','MongoDB, object storage, Redis, audit store, backups','Highly restricted','Encryption, private endpoints, KMS, retention and access review'],['External source zone','API Setu, GSTN, Udyam, MCA21, DigiLocker, EPFO, ESIC and others','External authority','Provider approval, source-specific contract, mTLS/OAuth/API key and logging'],['Operations zone','CI/CD, secrets, KMS, monitoring, SIEM, admin console','Privileged','Separate admin identities, MFA, break-glass and dual control']], [30*mm,57*mm,36*mm,42*mm],small=True))
S += [Spacer(1,8*mm),P('Primary attack paths','H2x')]
S += bullets(['Malicious document -> parser/OCR exploit -> worker compromise. Mitigation: file type allowlist, size limits, antivirus, sandboxed workers and no shell execution.', 'Compromised user -> over-broad case access. Mitigation: tenant and case-level authorization, purpose checks, short-lived tokens and access logging.', 'Leaked adapter credential -> unauthorised portal access. Mitigation: secret vault, one credential per source, egress allowlist, rotation and provider-side scope.', 'Prompt injection in a tender PDF -> model follows document instructions. Mitigation: treat documents as data, isolate prompts, structured output validation and deterministic rules.', 'Stale or manipulated source response -> wrong recommendation. Mitigation: freshness windows, response hashes, source timestamps, replay detection and Review Required state.'])
S.append(PageBreak())

