S += [P('3 Target architecture','H1x'),P('Use a modular monolith for the SIH build and a controlled service boundary for production. The core remains a Node.js and Express application. Heavy or risky work runs in separate workers so the API process never handles untrusted files or long portal calls directly.', 'Bodyx')]
S.append(tbl([['PLANE','COMPONENTS','NETWORK / ROUTE','SECURITY PURPOSE'],['Presentation plane','React + Vite officer console and bidder pre-check','Browser -> HTTPS -> WAF -> frontend/API','No portal credentials or raw source tokens in browser'],['Control plane','Express API, authentication, authorization, policy and case orchestration','Private app subnet; API gateway routes only','Central point for purpose, role and source policy checks'],['Evidence plane','Object storage, document metadata, extracted fields, source snapshots','Private data endpoints only','Separate original files from derived evidence; encrypt both'],['Verification plane','Adapter orchestrator, source-specific clients, retry/circuit breaker logic','Worker subnet -> approved egress gateway -> source','One adapter, one policy, one credential and one audit trail per source'],['Decision plane','Rule engine, risk assessment, recommendation and officer decision','Internal service calls; no direct external calls','AI advisory; deterministic rules and human authority'],['Operations plane','Queue, metrics, traces, logs, secrets, KMS and SIEM','Management subnet; admin access via VPN/bastion','Separate operational privilege from case access']], [30*mm,53*mm,54*mm,28*mm],small=True))
S += [Spacer(1,8*mm),P('Reference route model','H2x'),P('<b>Browser -> DNS/TLS -> WAF -> Express API -> authorization/purpose check -> job queue -> source adapter -> egress gateway -> authorised external API -> normalizer -> evidence store -> rule engine -> officer review -> audit export</b>', 'Quote'),P('The route is intentionally longer than a direct browser-to-portal call. Each boundary exists to keep secrets, raw responses, retries, data transformation and accountability under platform control.', 'Bodyx'),PageBreak()]

