# 13 audit
S += [P('13 Compliance, audit and explainability','H1x'),P('The audit trail is a security control and a procurement control. It must answer who accessed what, why, from which source, under which policy, using which rule version, with which evidence, and what the officer decided.', 'Bodyx')]
S.append(tbl([['EVENT','MINIMUM RECORD'],['Access','actor_id, role, case_id, purpose, fields viewed, timestamp, client context'],['Source request','adapter, credential_ref, policy decision, request hash, correlation ID, requested fields'],['Source response','provider status, response hash, source timestamp, normalized result, raw reference, freshness'],['Document action','upload, download, reveal, OCR, correction, export, deletion, actor and reason'],['Rule action','rule ID/version, inputs, evidence references, result, severity, engine version'],['Decision','officer, outcome, reason, unresolved findings, input snapshot hash, signed time'],['Admin action','credential change, role change, rule publish, retention override, break-glass reason']], [38*mm,137*mm],small=True))
S += [Spacer(1,8*mm),P('Tamper evidence','H2x'),P('Use append-only audit events, event chaining or a signed daily digest. The goal is to make unauthorised editing detectable. An “immutable database” claim is not enough unless the platform also controls who can delete, alter, export or re-index the audit store.', 'Bodyx'),PageBreak()]

# 14 availability
S += [P('14 Failure and availability architecture','H1x'),P('The system must stay safe when external systems are unreliable. A source outage must not become an automatic pass, and a retry storm must not become a denial-of-service attack against a government platform.', 'Bodyx')]
S.append(tbl([['FAILURE','SYSTEM STATE','MITIGATION'],['Timeout','Pending Re-verification','Short timeout, bounded retry, exponential backoff and visible freshness'],['Rate limit','Pending with retry-after','Bottleneck per adapter, queue backpressure and provider quota dashboard'],['Auth denied','Integration Blocked','Do not retry blindly; rotate or re-authorise under operator workflow'],['Schema changed','Review Required','Contract test, response quarantine and adapter version rollback'],['Conflicting sources','Review Required','Preserve both evidence records; do not pick one silently'],['OCR low confidence','Review Required','Manual correction with page-level evidence'],['Duplicate document','Review Required','Hash match and case history; never infer fraud automatically'],['Worker compromise','Job quarantined','Kill worker, revoke job token, preserve event, investigate and replay from clean input'],['Database unavailable','Read-only or degraded mode','No new final decisions; queue safe work; recover from backup and verify audit']], [33*mm,43*mm,99*mm],small=True))
S.append(PageBreak())

# 15 secure SDLC
S += [P('15 Secure development and verification plan','H1x'),P('Use OWASP ASVS 5.0 as the application security baseline and turn its requirements into testable acceptance criteria. ASVS is intended for security verification, developer guidance and procurement requirements. [R6]', 'Bodyx')]
S.append(tbl([['GATE','CHECKS','PASS CRITERION'],['Design','Data inventory, threat model, source authority review, trust boundaries','No unowned data flow or credential path'],['Code','TypeScript strict, review, dependency pinning, secret scan, lint and unit tests','No critical findings; sensitive code has an owner'],['API','Schema validation, authz tests, rate limits, SSRF tests, file upload tests','Unauthorised access and unsafe URLs fail closed'],['Integration','Adapter contract tests, mock and sandbox replay, rate-limit simulation','Every adapter handles success, timeout, denied and schema change'],['AI','Prompt injection, malformed output, leakage and bias tests','Model cannot directly execute a policy or call a source'],['Runtime','Container hardening, least privilege, egress allowlist, image scan','No public data service; only approved routes'],['Audit','Replay case from stored evidence and verify decision hash','Same inputs and rule version reproduce the result'],['Release','Security sign-off, rollback plan, restore test and incident contact','Release owner accepts residual risk']], [29*mm,91*mm,55*mm],small=True))
S += [Spacer(1,8*mm),P('Minimum test cases','H2x')]
S += bullets(['User from organisation A attempts to read organisation B case.', 'Adapter receives a bidder-controlled URL and attempts SSRF.', 'A PDF contains prompt-like text instructing the model to ignore policy.', 'A portal returns ACTIVE with an old source timestamp.', 'A source returns a different legal name from the uploaded certificate.', 'A worker job is replayed after a timeout.', 'An officer exports a report containing masked and unmasked fields.', 'A revoked credential is still present in a worker process.'])
S.append(PageBreak())

# 16 implementation
S += [P('16 Implementation roadmap','H1x'),P('Build the security boundary and evidence contract before adding all ten integrations. The fastest safe route is to prove one complete path, then replicate the adapter pattern.', 'Bodyx')]
S.append(tbl([['PHASE','DELIVERABLES','EXIT CRITERION'],['0. Policy and scope','Data inventory, source authority matrix, consent/authority fields, synthetic test pack','Team agrees what each source is allowed to provide'],['1. Secure foundation','Node.js/Express API, OIDC/RBAC, private storage, secret management, audit events','No browser-to-source calls; access events are visible'],['2. Evidence pipeline','Upload, scan, hash, object storage, OCR worker, structured extraction','A reviewer can trace a field to page and checksum'],['3. Adapter framework','Common adapter contract, mock API Setu, GST and Udyam adapters','Success and failure states are consistent'],['4. Rule and decision engine','Tender versioning, requirement editor, deterministic rules, officer decision','Same evidence and rule version reproduce same result'],['5. Source expansion','MCA21, DigiLocker, Startup India, NSIC, EPFO/ESIC, BIS and debarment sources','Each source has owner, approval, scopes, freshness and runbook'],['6. Pilot hardening','Threat model, ASVS verification, penetration test, restore drill, DPIA/legal review','Pilot go/no-go decision with residual-risk register']], [29*mm,91*mm,55*mm],small=True))
S += [Spacer(1,8*mm),P('Team ownership','H2x')]
S.append(tbl([['ROLE','OWNS'],['Platform lead','Network, deployment, secrets, observability and incident response'],['Integration lead','Adapter contract, source onboarding, provider terms and connector tests'],['Document/AI lead','Safe file processing, OCR, extraction, model policy and evaluation'],['Rules lead','Tender taxonomy, rule registry, effective dates and test fixtures'],['Product/security lead','Threat model, data inventory, RBAC, audit, privacy review and officer workflow']], [38*mm,137*mm]))
S.append(PageBreak())

# 17 decisions
S += [P('17 Decisions the team should freeze now','H1x')]
S += bullets(['Use Node.js 24 LTS and TypeScript in strict mode for the API and workers.', 'Use Express 5.x with a modular monolith, not microservices, for the SIH MVP.', 'Use MongoDB for case/evidence metadata, private S3-compatible object storage for originals, and Redis + BullMQ for asynchronous work.', 'Use OIDC/SAML with institutional identity where possible. Do not build a custom password system for the demo.', 'Use mock or sandbox connectors and synthetic data until each real provider approves access.', 'Make every source call pass a purpose and authority check before it leaves the private network.', 'Treat AI output as candidate evidence or explanation. Deterministic rules and the Procurement Officer control the decision.', 'Define retention, deletion, source freshness and audit export policies before collecting real bidder data.', 'Use OWASP ASVS 5.0 as the security acceptance baseline and document residual risks.'])
S += [Spacer(1,8*mm),P('What the architecture prevents','H2x'),P('It prevents a frontend token leak from becoming a government portal breach, prevents one integration failure from producing a silent pass, prevents an LLM from becoming the final decision-maker, and makes a later source replacement possible without rewriting the compliance engine.', 'Quote'),PageBreak()]

# 18 appendix contracts
